// Generated by AI (UnitTest MCP)
import assert from "node:assert/strict";
import test from "node:test";

import { parseEnvFile, resolveEnv } from "./run-ackplane.mjs";

test("parseEnvFile reads simple KEY=VALUE lines", () => {
  const text = "ACKPLANE_PORT=8443\nACKPLANE_BRIDGE_LISTEN=127.0.0.1:18150\n";
  assert.deepEqual(parseEnvFile(text), {
    ACKPLANE_PORT: "8443",
    ACKPLANE_BRIDGE_LISTEN: "127.0.0.1:18150",
  });
});

test("parseEnvFile skips blank lines and #-comments", () => {
  const text = [
    "# a leading comment",
    "",
    "ACKPLANE_PORT=8443",
    "   ",
    "# a trailing comment",
    "ACKPLANE_VERSION=dev",
  ].join("\n");
  assert.deepEqual(parseEnvFile(text), {
    ACKPLANE_PORT: "8443",
    ACKPLANE_VERSION: "dev",
  });
});

test("parseEnvFile only splits on the first '=', so a value may contain one", () => {
  const text =
    "ACKPLANE_DATABASE_URL=postgresql://ackplane:pw@127.0.0.1:5432/ackplane?sslmode=disable";
  assert.deepEqual(parseEnvFile(text), {
    ACKPLANE_DATABASE_URL:
      "postgresql://ackplane:pw@127.0.0.1:5432/ackplane?sslmode=disable",
  });
});

test("parseEnvFile trims surrounding whitespace from both key and value", () => {
  const text = "  ACKPLANE_PORT   =   8443  \n";
  assert.deepEqual(parseEnvFile(text), { ACKPLANE_PORT: "8443" });
});

test("parseEnvFile ignores a line with no '=' rather than throwing", () => {
  const text = "ACKPLANE_PORT=8443\nnot a valid line\nACKPLANE_VERSION=dev";
  assert.deepEqual(parseEnvFile(text), {
    ACKPLANE_PORT: "8443",
    ACKPLANE_VERSION: "dev",
  });
});

test("resolveEnv lets an already-set shell variable win over .env", () => {
  const resolved = resolveEnv("no-such-file.env", { ACKPLANE_PORT: "9999" });
  assert.equal(resolved.ACKPLANE_PORT, "9999");
});

test("resolveEnv falls back to an empty object for a missing .env file", () => {
  assert.deepEqual(resolveEnv("no-such-file.env", {}), {});
});
